const CHAPTER_DATA_FILES = {
  1: "./data/chapter1.js",
  2: "./data/chapter2.js",
  3: "./data/chapter3.js",
  4: "./data/chapter4.js"
};

const CHAPTER_FIGURE_FILES = {
  1: "./data/chapter1-figures.js",
  2: "./data/chapter2-figures.js",
  3: "./data/chapter3-figures.js"
};

const chapterDataCache = new Map();
const chapterLoadPromises = new Map();
const chapterFigureLoadPromises = new Map();

// Metadata is enough for startup screens, progress counts and state migration.
let ALL_QUESTIONS = QUESTION_INDEX.map(q => ({ ...q, __metaOnly: true }));
const FIGURE_LIBRARY = {};

async function loadChapterData(chapter) {
  const ch = Number(chapter);
  if (chapterDataCache.has(ch)) return chapterDataCache.get(ch);
  if (chapterLoadPromises.has(ch)) return chapterLoadPromises.get(ch);

  const file = CHAPTER_DATA_FILES[ch];
  if (!file) throw new Error(`第${ch}章のデータファイルが登録されていません。`);

  const promise = import(`${file}?v=${encodeURIComponent(APP_VERSION)}&t=${Date.now()}`)
    .then(mod => {
      const data = mod.default || mod;
      if (!data || !Array.isArray(data.questions)) {
        throw new Error(`第${ch}章データの形式が正しくありません。`);
      }

      const loaded = data.questions;
      const existing = new Map(ALL_QUESTIONS.map(q => [q.id, q]));
      loaded.forEach(q => existing.set(q.id, q));
      ALL_QUESTIONS = Array.from(existing.values());

      const result = { chapter: ch, questions: loaded, figures: {} };
      chapterDataCache.set(ch, result);
      return result;
    })
    .catch(error => {
      chapterLoadPromises.delete(ch);
      throw error;
    });

  chapterLoadPromises.set(ch, promise);
  return promise;
}

async function loadChapterFigures(chapter) {
  const ch = Number(chapter);
  const file = CHAPTER_FIGURE_FILES[ch];
  if (!file) return {};
  if (chapterFigureLoadPromises.has(ch)) return chapterFigureLoadPromises.get(ch);

  const promise = import(`${file}?v=${encodeURIComponent(APP_VERSION)}&t=${Date.now()}`)
    .then(mod => {
      const data = mod.default || mod;
      const figures = data?.figures || {};
      Object.entries(figures).forEach(([id, fig]) => {
        FIGURE_LIBRARY[id] = fig;
      });
      return figures;
    })
    .catch(error => {
      chapterFigureLoadPromises.delete(ch);
      throw error;
    });

  chapterFigureLoadPromises.set(ch, promise);
  return promise;
}

async function ensureChapterLoaded(chapter) {
  return loadChapterData(chapter);
}

async function ensureAllQuestionsLoaded() {
  const chapters = [...new Set(QUESTION_INDEX.map(q => q.chapter))];
  await Promise.all(chapters.map(ch => loadChapterData(ch)));
  return ALL_QUESTIONS;
}

async function ensureAllFiguresLoaded() {
  const chapters = [...new Set(QUESTION_INDEX.map(q => q.chapter))];
  await Promise.all(chapters.map(ch => loadChapterFigures(ch)));
  return FIGURE_LIBRARY;
}

async function ensureQuestionsForIds(ids) {
  const chapters = [...new Set(
    (ids || []).map(id => QUESTION_INDEX.find(q => q.id === id)?.chapter).filter(Boolean)
  )];
  await Promise.all(chapters.map(ch => loadChapterData(ch)));
  return ALL_QUESTIONS;
}


// v0.2.77: 問題データ初期化後に学習記録を現在の問題IDへ同期。
// これより前に実行するとALL_QUESTIONSのconst初期化前参照で起動が停止する。
migrateStateToCurrentSchema();

let practiceQueue = [];

let practiceLabel = "第1章すべて";
let practiceSessionAnswers = {};
let practiceCompleted = false;

/* v0.2.73: 演習途中保存・再開・離脱確認を復旧。 */
function getSavedPracticeSession() {
  const s = state && state.practiceSession;
  if (!s || s.completed || !Array.isArray(s.queue) || !s.queue.length) return null;
  const validQueue = s.queue.filter(id => ALL_QUESTIONS.some(q => q.id === id));
  if (!validQueue.length) return null;
  const idx = Math.max(0, Math.min(Number(s.currentIndex) || 0, validQueue.length - 1));
  return {
    active: !!s.active,
    queue: validQueue,
    label: s.label || "問題演習",
    currentIndex: idx,
    answers: (s.answers && typeof s.answers === "object") ? { ...s.answers } : {},
    startedAt: s.startedAt || new Date().toISOString(),
    pausedAt: s.pausedAt || null
  };
}

function syncPracticeSessionToState(active = true) {
  if (!practiceQueue.length) {
    state.practiceSession = null;
  } else {
    state.practiceSession = {
      active,
      queue: [...practiceQueue],
      label: practiceLabel,
      currentIndex: state.currentIndex,
      answers: { ...practiceSessionAnswers },
      startedAt: state.practiceSession?.startedAt || new Date().toISOString(),
      pausedAt: active ? null : new Date().toISOString(),
      completed: false
    };
  }
  saveState();
}

function restorePracticeSession() {
  const saved = getSavedPracticeSession();
  if (!saved) return false;
  practiceQueue = saved.queue;
  practiceLabel = saved.label;
  practiceSessionAnswers = { ...saved.answers };
  practiceCompleted = false;
  state.currentIndex = saved.currentIndex;
  return true;
}

function hasActivePracticeSession() {
  const saved = getSavedPracticeSession();
  return !!saved && saved.active !== false;
}

function pausePracticeSession() {
  if (!practiceQueue.length) return;
  syncPracticeSessionToState(false);
}

async function resumePracticeSession() {
  if (!restorePracticeSession()) {
    alert("再開できる途中の演習がありません。");
    renderPracticeSelector();
    return;
  }
  await ensureQuestionsForIds(practiceQueue);
  state.lastViewed = "practice";
  syncPracticeSessionToState(true);
  renderQuestion();
}

function discardPracticeSession() {
  practiceQueue = [];
  practiceLabel = "第1章すべて";
  practiceSessionAnswers = {};
  practiceCompleted = false;
  state.currentIndex = 0;
  state.practiceSession = null;
  saveState();
}

function confirmPracticeLeave(destination) {
  // 「途中保存済み（paused）」は、再度ページを移動するたびに確認しない。
  // 実際に演習画面を離れる直前の active セッションだけを対象にする。
  if (!hasActivePracticeSession() || state.lastViewed !== "practice") {
    destination();
    return;
  }
  const queue = getPracticeQuestions();
  const position = Math.min(state.currentIndex + 1, queue.length);
  const ok = confirm(`演習の途中です。\n\n${practiceLabel}\n現在 ${position} / ${queue.length} 問\n\n途中経過を保存して移動しますか？\n「キャンセル」で演習を続けられます。`);
  if (!ok) return;
  pausePracticeSession();
  destination();
}

function loadState() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
    return saved ? { ...defaultState, ...saved } : { ...defaultState };
  } catch { return { ...defaultState }; }
}

function saveState() { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); }

function migrateStateToCurrentSchema() {
  const originalAnswers = (state.answers && typeof state.answers === "object")
    ? state.answers
    : {};
  const originalBookmarks = (state.bookmarks && typeof state.bookmarks === "object")
    ? state.bookmarks
    : {};

  // 既存記録は、現在の問題データに存在しないIDも含めて保持する。
  // 問題を将来整理・差し替えしても、過去記録そのものを破棄しない。
  const normalizedAnswers = { ...originalAnswers };
  const normalizedBookmarks = { ...originalBookmarks };
  Object.keys(normalizedBookmarks).forEach(id => {
    normalizedBookmarks[id] = !!normalizedBookmarks[id];
  });

  // 将来の問題ID変更時も、旧記録を新IDへ引き継げるようにする。
  Object.entries(originalAnswers).forEach(([oldId, record]) => {
    const newId = QUESTION_ID_ALIASES[oldId];
    if (!newId || normalizedAnswers[newId] !== undefined) return;
    if (ALL_QUESTIONS.some(q => q.id === newId)) {
      normalizedAnswers[newId] = record;
    }
  });
  Object.entries(originalBookmarks).forEach(([oldId, value]) => {
    const newId = QUESTION_ID_ALIASES[oldId];
    if (!newId || normalizedBookmarks[newId] !== undefined) return;
    if (ALL_QUESTIONS.some(q => q.id === newId)) {
      normalizedBookmarks[newId] = !!value;
    }
  });

  const before = JSON.stringify({
    answers: state.answers || {},
    bookmarks: state.bookmarks || {},
    schemaVersion: state.schemaVersion || 0
  });
  const after = JSON.stringify({
    answers: normalizedAnswers,
    bookmarks: normalizedBookmarks,
    schemaVersion: STATE_SCHEMA_VERSION
  });

  state.answers = normalizedAnswers;
  state.bookmarks = normalizedBookmarks;
  state.schemaVersion = STATE_SCHEMA_VERSION;

  if (before !== after) {
    saveState();
    console.info("CPTmate 学習記録を現在の問題データへ同期しました。", {
      schemaVersion: STATE_SCHEMA_VERSION,
      answers: Object.keys(state.answers).length,
      bookmarks: Object.keys(state.bookmarks).length
    });
  }
}

// Migration is intentionally invoked after ALL_QUESTIONS is initialized.
function getCurrentAnswer(id) {
  return state.answers && state.answers[id] ? state.answers[id] : null;
}

function answeredCount() {
  return ALL_QUESTIONS.filter(q => !!getCurrentAnswer(q.id)).length;
}

function correctCount() {
  return ALL_QUESTIONS.filter(q => getCurrentAnswer(q.id)?.correct === true).length;
}

function accuracy() {
  const n = answeredCount();
  return n ? Math.round(correctCount() / n * 100) : 0;
}


