function renderExplanationTable(q) {
  if (!q || !q.explanationTable) return "";
  const table = q.explanationTable;
  const headers = Array.isArray(table.headers) ? table.headers : [];
  const rows = Array.isArray(table.rows) ? table.rows : [];

  const headerHtml = headers.map(header => `<th>${escapeGalleryText(header)}</th>`).join("");
  const rowsHtml = rows.map(row => `
    <tr>
      ${row.map((cell, index) => index === 0
        ? `<th scope="row">${escapeGalleryText(cell)}</th>`
        : `<td>${escapeGalleryText(cell)}</td>`
      ).join("")}
    </tr>
  `).join("");

  return `
    <div class="explanation-table-wrap">
      <div class="explanation-table-title">${escapeGalleryText(table.title || "確認表")}</div>
      <div class="explanation-table-scroll">
        <table class="explanation-table">
          <thead><tr>${headerHtml}</tr></thead>
          <tbody>${rowsHtml}</tbody>
        </table>
      </div>
    </div>
  `;
}

function renderQuestion() {
  ensureOptionReviewStyles();
  ensureChoiceFeedbackStyles();
  setActiveNav("practice");
  const queue = getPracticeQuestions();
  if (!queue.length) { renderPracticeSelector(); return; }
  if (practiceCompleted) {
    renderPracticeComplete();
    return;
  }
  const q = queue[state.currentIndex];
  const sourceBadge = renderSourceBadge(q);
  const saved = practiceSessionAnswers[q.id];
  const hasAnswered = !!state.answers[q.id];
  const bookmarked = !!state.bookmarks[q.id];
  const answerStatus = hasAnswered
    ? '<span class="question-answer-status answered">回答済み</span>'
    : '<span class="question-answer-status unanswered">未解答</span>';
  const letters = ["A", "B", "C", "D"];

  let choices = q.choices.map((choice, i) => {
    let cls = "";
    if (saved) {
      if (i === q.answer) cls = "correct";
      else if (i === saved.selected && !saved.correct) cls = "wrong";
    }
    const feedbackMark = saved
      ? `<span class="choice-feedback-mark ${i === q.answer ? "is-correct" : "is-wrong"}" aria-hidden="true">${i === q.answer ? "○" : "×"}</span>`
      : "";
    return `<button class="choice ${cls}" ${saved ? "disabled" : ""} onclick="answerQuestion(${i})">
      <span class="letter">${letters[i]}</span><span class="choice-text">${choice}</span>${feedbackMark}
    </button>`;
  }).join("");

  // 「question」図は回答前から表示。
  // 「after」図は回答後の解説欄だけに表示。
  const questionFigure = (!saved && q.figureMode === "question")
    ? renderQuestionFigure(q, "question")
    : "";

  const result = saved ? `
    <div class="result ${saved.correct ? "correct" : "wrong"}">
      <div class="result-status">
        <span class="result-status-icon">${saved.correct ? "⭕" : "❌"}</span>
        <span>${saved.correct ? "正解" : "不正解"}</span>
      </div>

      ${saved.correct ? "" : `
        <div class="correct-answer-line">
          正解：${letters[q.answer]}　${q.choices[q.answer]}
        </div>
      `}

      <div class="explanation">
        <strong>解説</strong>
        <br>
        ${q.explanation}
        ${renderExplanationTable(q)}
        ${q.figureMode === "after" ? renderQuestionFigure(q, "explanation") : ""}
      </div>

      ${renderOptionReview(q)}
    </div>

    <div class="post-answer-actions">
      <button class="secondary-btn full" onclick="retryQuestion()">もう一度この問題を解く</button>
      <div class="question-nav-actions question-nav-actions-below-card">
        <button class="secondary-btn question-nav-btn" onclick="previousQuestion()" ${state.currentIndex <= 0 ? "disabled" : ""}>‹ 前の問題</button>
        <button class="primary-btn question-nav-btn" onclick="nextQuestion()">次の問題 ›</button>
      </div>
    </div>
  ` : "";

  screenEl().innerHTML = `
    <div class="back-row">
      <button class="back-btn" onclick="openPracticeSelectorClean()">‹</button>
      <h2>問題演習</h2>
    </div>
    <div class="practice-mode-bar">${practiceLabel}</div>

    <div class="question-nav-actions question-nav-actions-above-card">
      <button class="secondary-btn question-nav-btn" onclick="previousQuestion()" ${state.currentIndex <= 0 ? "disabled" : ""}>‹ 前の問題</button>
      <button class="primary-btn question-nav-btn" onclick="nextQuestion()">次の問題 ›</button>
    </div>

    <section class="card">
      <div class="question-head">
        <div class="question-category">
          <span class="question-chapter">第${q.chapter}章</span>
          <span class="question-category-name">${q.category}</span>
        </div>
        <span class="question-progress">この演習：${state.currentIndex + 1} / ${queue.length}</span>
      </div>
      <div class="question-info-row">
        <div class="source-badge-wrap">${sourceBadge}</div>
        <div class="question-action-group">
          ${answerStatus}
          <button class="bookmark" type="button" aria-label="${bookmarked ? "お気に入りから削除" : "お気に入りに追加"}" onclick="toggleBookmark('${q.id}')">${bookmarked ? "★" : "☆"}</button>
        </div>
      </div>

      ${questionFigure}
      <p class="question-text">${q.question}</p>
      <div>${choices}</div>
      ${result}
    </section>
  `;
}

function retryQuestion() {
  const queue = getPracticeQuestions();
  const q = queue[state.currentIndex];
  delete practiceSessionAnswers[q.id];
  renderQuestion();
}


function answerQuestion(selected) {
  const queue = getPracticeQuestions();
  const q = queue[state.currentIndex];
  const correct = selected === q.answer;
  const record = { selected, correct, answeredAt: new Date().toISOString() };
  state.answers[q.id] = record;
  practiceSessionAnswers[q.id] = record;
  syncPracticeSessionToState(true);
  renderQuestion();
}

function previousQuestion() {
  const queue = getPracticeQuestions();
  if (state.currentIndex <= 0) return;
  state.currentIndex -= 1;
  syncPracticeSessionToState(true);
  renderQuestion();
}

function nextQuestion() {
  const queue = getPracticeQuestions();
  if (state.currentIndex >= queue.length - 1) {
    practiceCompleted = true;
    state.lastViewed = "practice-complete";
    state.practiceSession = null;
    saveState();
    renderPracticeComplete();
    return;
  }
  state.currentIndex += 1;
  syncPracticeSessionToState(true);
  renderQuestion();
}

function toggleBookmark(id) {
  state.bookmarks[id] = !state.bookmarks[id];
  saveState();
  renderQuestion();
}

function wrongCount() {
  return ALL_QUESTIONS.filter(q => getCurrentAnswer(q.id)?.correct === false).length;
}

async function renderReview() {
  setActiveNav("review");
  await ensureAllQuestionsLoaded();
  const wrong = ALL_QUESTIONS.filter(q => state.answers[q.id] && !state.answers[q.id].correct);

  screenEl().innerHTML = `
    <div class="back-row"><h2>復習</h2></div>
    <section class="card">
      <h3>間違えた問題</h3>
      <p style="color:var(--muted);line-height:1.7;margin-top:0;">一度間違えた問題をもう一度解き直します。1問を開始すると、その下にある復習問題を順番に続けて解けます。</p>
      ${wrong.length ? wrong.map(q => `
        <div class="list-item">
          <div><strong>${q.category}</strong><br><small>${q.question}</small></div>
          <button class="secondary-btn" onclick="startReview('${q.id}')">解く</button>
        </div>
      `).join("") : `<div class="empty">まだ間違えた問題はありません。<br>問題を解いてみましょう。</div>`}
    </section>
  `;
}

async function renderFavorites() {
  setActiveNav("favorites");
  await ensureAllQuestionsLoaded();
  const favorites = ALL_QUESTIONS.filter(q => state.bookmarks[q.id]);

  screenEl().innerHTML = `
    <div class="back-row"><h2>お気に入り</h2></div>
    <section class="card">
      <h3>⭐ お気に入りの問題</h3>
      <p style="color:var(--muted);line-height:1.7;margin-top:0;">あとで見返したい問題をここにまとめています。</p>
      ${favorites.length ? favorites.map(q => `
        <div class="list-item">
          <div><strong>${q.category}</strong><br><small>${q.question}</small></div>
          <button class="secondary-btn" onclick="startSpecific('${q.id}')">解く</button>
        </div>
      `).join("") : `<div class="empty">お気に入りに登録した問題はありません。<br>問題画面の☆を押して登録できます。</div>`}
    </section>
  `;
}

function startReview(id) {
  const wrong = ALL_QUESTIONS.filter(q => state.answers[q.id] && !state.answers[q.id].correct);
  const index = wrong.findIndex(q => q.id === id);
  if (index < 0) return;
  startPracticeQueue(
    wrong.map(q => q.id),
    `復習・${wrong.length}問`,
    index
  );
}

async function startSpecific(id) {
  const meta = QUESTION_INDEX.find(q => q.id === id);
  if (meta) await ensureChapterLoaded(meta.chapter);
  const q = ALL_QUESTIONS.find(q => q.id === id);
  if (q) startPracticeQueue([q.id], `${q.category}・1問`);
}

