function compareVersions(a, b) {
  const pa = String(a).split(".").map(n => parseInt(n, 10) || 0);
  const pb = String(b).split(".").map(n => parseInt(n, 10) || 0);
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const x = pa[i] || 0;
    const y = pb[i] || 0;
    if (x > y) return 1;
    if (x < y) return -1;
  }
  return 0;
}

async function checkForAppUpdate() {
  const status = document.getElementById("updateStatus");
  const currentVersion = APP_VERSION;
  if (status) status.textContent = "最新版を確認しています…";

  try {
    // version.jsonではなく、公開中のapp.js自身から最新版を判定する。
    // version.jsonの更新漏れがあっても、アプリ本体のバージョンを正しく検出できる。
    const checkStamp = Date.now();
    const latestAppUrl = `app.js?check=${checkStamp}`;
    const latestAppRes = await fetch(latestAppUrl, {
      cache: "no-store",
      headers: { "Cache-Control": "no-cache" }
    });
    if (!latestAppRes.ok) {
      throw new Error(`app.js: HTTP ${latestAppRes.status}`);
    }

    const latestAppText = await latestAppRes.text();
    const latestMatch = latestAppText.match(/const APP_VERSION\s*=\s*"([^"]+)"/);
    if (!latestMatch || !latestMatch[1]) {
      throw new Error("公開中のapp.jsからバージョンを取得できません。");
    }

    const latestVersion = String(latestMatch[1]).trim();

    if (compareVersions(latestVersion, currentVersion) <= 0) {
      if (status) status.textContent = `最新版です（v${currentVersion}）`;
      return;
    }

    if (!confirm(`最新版 v${latestVersion} が利用できます。\n\n最新版へ更新しますか？`)) {
      if (status) status.textContent = `現在のバージョン：v${currentVersion}`;
      return;
    }

    if (status) status.textContent = `v${latestVersion} のファイルを確認しています…`;

    // 更新対象を再取得して、公開中のapp.jsが本当に最新版であることを確認する。
    // URLに時刻を付けることで、iPhone Safari / ホーム画面PWAの
    // 古い静的ファイルを再利用しにくくする。
    const assetNames = ["app.js", "style.css"];
    for (const assetName of assetNames) {
      const assetUrl = `${assetName}?v=${encodeURIComponent(latestVersion)}&update=${Date.now()}`;
      const assetRes = await fetch(assetUrl, {
        cache: "no-store",
        headers: { "Cache-Control": "no-cache" }
      });
      if (!assetRes.ok) throw new Error(`${assetName}: HTTP ${assetRes.status}`);

      const assetText = await assetRes.text();
      if (assetName === "app.js") {
        const match = assetText.match(/const APP_VERSION\s*=\s*"([^"]+)"/);
        if (!match || compareVersions(match[1], latestVersion) !== 0) {
          throw new Error(`app.jsのバージョンが一致しません（取得: ${match?.[1] || "不明"} / 最新: ${latestVersion}）`);
        }
      }
    }

    if (status) status.textContent = `v${latestVersion} を確認しました。再読み込みしています…`;

    // index.html側も app.js?v=...&t=時刻 で読み込む構造なので、
    // ここではブラウザ標準の再読み込みを行えば最新版app.jsが実行される。
    window.location.reload();
  } catch (error) {
    console.error("CPTmate update check failed:", error);
    if (status) status.textContent = "更新確認に失敗しました。";
    alert(`最新版への更新に失敗しました。\n\n${error.message || error}\n\n通信状態とGitHub Pagesの公開状態を確認してください。`);
  }
}

function exportBackup() {
  const payload = {
    app: "CPTmate",
    version: APP_VERSION,
    exportedAt: new Date().toISOString(),
    state
  };
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `CPTmate_backup_${new Date().toISOString().slice(0,10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
}

function importBackup() {
  const input = document.getElementById("backupFileInput");
  if (input) input.click();
}

function importBackupFile(event) {
  const file = event.target.files?.[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = () => {
    try {
      const payload = JSON.parse(String(reader.result || ""));
      if (!payload || payload.app !== "CPTmate" || !payload.state) {
        throw new Error("invalid backup");
      }
      if (!confirm("バックアップの学習データで現在の学習データを置き換えます。よろしいですか？")) return;
      state = {
        ...defaultState,
        ...payload.state,
        answers: { ...(payload.state.answers || {}) },
        bookmarks: { ...(payload.state.bookmarks || {}) }
      };
      saveState();
      renderSettings();
      alert("学習データを復元しました。");
    } catch (error) {
      console.error("CPTmate backup restore failed:", error);
      alert("バックアップを読み込めませんでした。CPTmateで作成したバックアップJSONを選択してください。");
    } finally {
      event.target.value = "";
    }
  };
  reader.readAsText(file);
}

function resetProgress() {
  if (!confirm("学習履歴とブックマークをリセットします。よろしいですか？")) return;
  state = { ...defaultState };
  saveState();
  renderSettings();
}

document.querySelectorAll(".nav-btn").forEach(btn => {
  btn.addEventListener("click", () => {
    const nav = btn.dataset.nav;
    const destination = () => {
      // ナビゲーション先へ移動した時点で lastViewed も更新する。
      // これにより、途中保存後に別ページへ移動しても、次のページ遷移で
      // 「演習の途中です。」が再表示されない。
      if (nav === "home") { state.lastViewed = "home"; mergeHomeAndStatsNavigation(); renderHome(); }
      if (nav === "favorites") { state.lastViewed = "favorites"; renderFavorites(); }
      if (nav === "practice") { state.lastViewed = "practice-selector"; renderPracticeSelector(); }
      if (nav === "review") { state.lastViewed = "review"; renderReview(); }
      if (nav === "stats") { state.lastViewed = "stats"; renderStats(); }
      if (nav === "settings") { state.lastViewed = "settings"; renderSettings(); }
      saveState();
    };
    confirmPracticeLeave(destination);
  });
});


// 起動スプラッシュは初期ホーム描画より先に終了タイマーを開始する。
// ホーム側の例外で起動ロゴが残り続けることを防止する。
if (typeof window.__cptmateFinishSplash === "function") {
  window.__cptmateFinishSplash();
}
try {
  renderHome();
} catch (error) {
  console.error("[CPTmate] initial renderHome failed:", error);
  const screen = document.getElementById("screen");
  if (screen) {
    screen.innerHTML = `
      <div class="card" style="margin:24px;padding:24px;text-align:center;">
        <h2 style="margin-top:0;">CPTmate</h2>
        <p>ホーム画面の読み込みに失敗しました。</p>
        <button class="btn primary" onclick="location.reload()">再読み込み</button>
      </div>
    `;
  }
}
